use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->SemioPresentationSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let frame=SlideFrame{origin:SemioPoint2{x:-1.0,y:2.0},width:3.5,height:4.25};let kinds=vec![PlaceholderKind::Title,PlaceholderKind::Subtitle,PlaceholderKind::Body,PlaceholderKind::Footer,PlaceholderKind::SlideNumber,PlaceholderKind::DateTime,PlaceholderKind::Other{value:"".into()}];let mut shapes:Vec<SlideShape>=kinds.into_iter().map(|kind|SlideShape::Placeholder{frame,kind}).collect();shapes.push(SlideShape::TextBox{frame,blocks:vec![DocBlock::Paragraph{style_id:Some("external-style".into()),runs:vec![crate::standards::v1::subsets::document::schema::snapshot::DocRun::plain(f["text"].as_str().unwrap())]},DocBlock::Image{image_id:"external-image".into(),alt:"".into(),width:None,height:Some(0.0)}]});shapes.push(SlideShape::Picture{frame,image:SlidePictureImage{asset_id:"".into(),mime:"image/png".into(),bytes:vec![0,255,127]}});shapes.push(SlideShape::Table{frame,rows:vec![SlideTableRow{cells:vec![SlideTableCell{blocks:vec![DocBlock::Quote{blocks:vec![DocBlock::PageBreak]}]},SlideTableCell{blocks:vec![]}]}]});SemioPresentationSnapshot{schema:f["schema"].as_str().unwrap().into(),masters:vec![SlideMaster{id:"master".into(),shapes:vec![SlideShape::Placeholder{frame,kind:PlaceholderKind::Title}]}],layouts:vec![SlideLayout{id:"layout".into(),master_id:"master".into(),shapes:vec![]}],slides:vec![Slide{id:f["slideId"].as_str().unwrap().into(),layout_id:Some("layout".into()),shapes,notes:vec![DocBlock::Code{language:Some("".into()),text:"notes".into()}]},Slide{id:"".into(),layout_id:None,shapes:vec![],notes:vec![]}]}}
fn project(s:&SemioPresentationSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioPresentationSnapshot,String>{SemioPresentationSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_semio_presentation_all_shapes_placeholders_typed_blocks_and_native_state(){let s=fixture();let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let r=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(r,s);assert_eq!(<SemioPresentationSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioPresentationSnapshot as store::ArtifactPack>::encode_pack(&s));assert_eq!(<SemioPresentationSnapshot as store::ArtifactDsl>::print_dsl(&r),<SemioPresentationSnapshot as store::ArtifactDsl>::print_dsl(&s));assert_eq!(restore(&project(&SemioPresentationSnapshot::default())).unwrap(),SemioPresentationSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_presentation_rejects_owner_fk_placeholder_and_block_aliases(){let original=project(&fixture());for change in 0..5{let mut db=original.clone();match change{0=>db.table_mut("semio_presentation_layout").unwrap().rows[0].values[4]=SqliteValue::Integer(999),1=>db.table_mut("semio_presentation_slide").unwrap().rows[0].values[4]=SqliteValue::Integer(999),2=>db.table_mut("semio_presentation_shape").unwrap().rows[0].values[3]=SqliteValue::Integer(1),3=>db.table_mut("semio_presentation_placeholder").unwrap().rows[0].values[2]=SqliteValue::Text("unexpected".into()),_=>{let id=db.table("semio_presentation_slide").unwrap().rows[0].integer(5).unwrap();db.table_mut("semio_presentation_slide").unwrap().rows[1].values[5]=SqliteValue::Integer(id);}}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioPresentationSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_presentation_independent_layout_master_join_and_picture_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=db.query('SELECT semio_presentation_layout.native_id AS layout,semio_presentation_master.native_id AS master FROM semio_presentation_layout JOIN semio_presentation_master ON master_id=semio_presentation_master.id').get();if(r.layout!=='layout'||r.master!=='master')throw Error('layout FK');if(db.query('SELECT length(bytes) AS n FROM semio_presentation_picture').get().n!==3)throw Error('picture bytes');db.query(\"UPDATE semio_presentation_picture SET mime='independently edited'\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();if let SlideShape::Picture{image,..}=&mut expected.slides[0].shapes[8]{image.mime="independently edited".into();}assert_eq!(r,expected);}

#[test]
fn sqlite_snapshot_semio_presentation_bare_owner_capability_native_payload_bridge(){let snapshot=fixture();let payload=store::os_io::IoPayload::Binary(<SemioPresentationSnapshot as store::ArtifactPack>::encode_pack(&snapshot));let codec=store::ArtifactCodec::bare::<SemioPresentationSnapshot,crate::standards::v1::subsets::presentation::schema::mutations::SemioPresentationMutation>("s.stdio.semio.presentation");let provider=codec.snapshot_sqlite.expect("owner must publish typed SQLite capability");assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<SemioPresentationSnapshot>()));let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"presentation".into()};let db=(provider.export)("s.stdio.semio.presentation",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let db=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=(provider.import)("s.stdio.semio.presentation",&dialect,db,SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(actual,payload);}

#[test]
fn sqlite_snapshot_semio_presentation_owned_numeric_bits_independent_sqlite(){use std::io::Write;use std::process::{Command,Stdio};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for(index,bits)in f["float64Bits"].as_array().unwrap().iter().enumerate(){let bits=u64::from_str_radix(bits.as_str().unwrap(),16).unwrap();let bits32=u32::from_str_radix(f["float32Bits"][index].as_str().unwrap(),16).unwrap();let v=f64::from_bits(bits);let _v32=f32::from_bits(bits32);let mut s=fixture();if let SlideShape::Placeholder{frame,..}=&mut s.masters[0].shapes[0]{frame.width=v;}let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!((match &r.masters[0].shapes[0]{SlideShape::Placeholder{frame,..}=>frame.width,_=>panic!("placeholder")}).to_bits(),bits);assert_eq!(<SemioPresentationSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioPresentationSnapshot as store::ArtifactPack>::encode_pack(&s));}}

#[test]
fn sqlite_snapshot_semio_presentation_typed_exact_subset_dialect_and_document_guard(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let snapshot=fixture();let database=project(&snapshot);let dialect=|v:&serde_json::Value|store::os_io::ArtifactDialect{artifact_kind:v["artifactKind"].as_str().unwrap().into(),standard:v["standard"].as_str().unwrap().into(),subset:v["subset"].as_str().unwrap().into()};let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&database,&mut control).unwrap().diagnostics.is_empty());for invalid in f["invalidSqliteDialects"].as_array().unwrap(){assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(invalid),&database,&mut control).is_err());}let mut malformed=database;malformed.table_mut("semio_presentation_document").unwrap().rows[0].values[1]=SqliteValue::Text("other schema".into());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&malformed,&mut control).is_err());}

#[test]
fn sqlite_snapshot_semio_presentation_bounded_native_text_binary_admission() {
    let snapshot=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"presentation".into()};
    let provider=<SemioPresentationSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let actual=(provider.import)("Semio native admission",&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
        let expected=match encoding{SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioPresentationSnapshot as store::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioPresentationSnapshot as store::ArtifactPack>::encode_pack(&snapshot))};assert_eq!(actual,expected);
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
    }
    let large= SemioPresentationSnapshot{schema:"x".repeat(100000),..snapshot};
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative||p.completed==0,SqliteDatabaseLimits::default())).is_err());
}
